## My answer to the user prompt

Here is a complete example using **eframe/egui** for the GUI, **rfd** for folder dialogs, and **notify** for filesystem monitoring.

The output and done folders are selectable but are not used to move files, since no processing or moving behavior was requested. The log displays filesystem event types and affected paths, including new-file events.

Create a project:

```sh
cargo new folder_monitor
cd folder_monitor
```

Add these dependencies to `Cargo.toml`:

```toml
[dependencies]
eframe = "0.27"
rfd = "0.14"
notify = "6.1"
```

Replace `src/main.rs` with:

```rust
use std::{
    path::PathBuf,
    sync::mpsc::{self, Receiver, Sender},
};

use eframe::egui;
use notify::{Event, RecommendedWatcher, RecursiveMode, Watcher};

struct FolderMonitor {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    log: Vec<String>,
    tx: Sender<notify::Result<Event>>,
    rx: Receiver<notify::Result<Event>>,
    // Retain the watcher: dropping it stops monitoring.
    watcher: Option<RecommendedWatcher>,
}

impl Default for FolderMonitor {
    fn default() -> Self {
        let (tx, rx) = mpsc::channel();
        Self {
            input: None,
            output: None,
            done: None,
            log: Vec::new(),
            tx,
            rx,
            watcher: None,
        }
    }
}

fn folder_row(ui: &mut egui::Ui, label: &str, path: &mut Option<PathBuf>) {
    ui.horizontal(|ui| {
        if ui.button(label).clicked() {
            if let Some(selected) = rfd::FileDialog::new().pick_folder() {
                *path = Some(selected);
            }
        }

        ui.label(
            path.as_ref()
                .map(|p| p.display().to_string())
                .unwrap_or_else(|| "Not selected".into()),
        );
    });
}

impl FolderMonitor {
    fn start(&mut self, ctx: &egui::Context) {
        let Some(input) = self.input.clone() else {
            self.log.push("Select an input folder first.".into());
            return;
        };

        let tx = self.tx.clone();
        let ctx = ctx.clone();

        let result = (|| -> notify::Result<RecommendedWatcher> {
            let mut watcher = notify::recommended_watcher(
                move |event: notify::Result<Event>| {
                    let _ = tx.send(event);
                    ctx.request_repaint();
                },
            )?;

            watcher.watch(&input, RecursiveMode::NonRecursive)?;
            Ok(watcher)
        })();

        match result {
            Ok(watcher) => {
                self.watcher = Some(watcher);
                self.log.push(format!("Watching {}", input.display()));
            }
            Err(error) => {
                self.log.push(format!("Could not start monitoring: {error}"));
            }
        }
    }
}

impl eframe::App for FolderMonitor {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        while let Ok(result) = self.rx.try_recv() {
            match result {
                Ok(event) => {
                    self.log.push(format!(
                        "Event: {:?}; paths: {}",
                        event.kind,
                        event.paths
                            .iter()
                            .map(|p| p.display().to_string())
                            .collect::<Vec<_>>()
                            .join(", ")
                    ));
                }
                Err(error) => self.log.push(format!("Watch error: {error}")),
            }
        }

        // Keep the displayed history bounded.
        if self.log.len() > 1000 {
            let excess = self.log.len() - 1000;
            self.log.drain(..excess);
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            // Avoid changing the displayed input while watching another path.
            ui.add_enabled_ui(self.watcher.is_none(), |ui| {
                folder_row(ui, "Select input folder", &mut self.input);
                folder_row(ui, "Select output folder", &mut self.output);
                folder_row(ui, "Select done folder", &mut self.done);
            });

            ui.horizontal(|ui| {
                let can_start = self.input.is_some() && self.watcher.is_none();
                if ui
                    .add_enabled(can_start, egui::Button::new("Start"))
                    .clicked()
                {
                    self.start(ctx);
                }

                if ui
                    .add_enabled(self.watcher.is_some(), egui::Button::new("Stop"))
                    .clicked()
                {
                    self.watcher = None;
                    self.log.push("Monitoring stopped.".into());
                }
            });

            ui.separator();
            ui.label("Filesystem events:");

            egui::ScrollArea::vertical()
                .stick_to_bottom(true)
                .show(ui, |ui| {
                    for entry in &self.log {
                        ui.label(entry);
                    }
                });
        });
    }
}

fn main() -> eframe::Result<()> {
    eframe::run_native(
        "Folder Monitor",
        eframe::NativeOptions::default(),
        Box::new(|_cc| Box::new(FolderMonitor::default())),
    )
}
```

