cd folder_monitor
```

Replace `Cargo.toml` with:

```toml
[package]
name = "folder_monitor"
version = "0.1.0"
edition = "2021"

[dependencies]
eframe = "0.27"
rfd = "0.14"
notify = "6.1"
```

Replace `src/main.rs` with:

```rust
use std::{
    collections::VecDeque,
    path::PathBuf,
    sync::mpsc::{self, Receiver},
    time::Duration,
};

use eframe::egui;
use notify::{Config, Event, RecommendedWatcher, RecursiveMode, Watcher};

#[derive(Default)]
struct FolderMonitor {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    watcher: Option<RecommendedWatcher>,
    receiver: Option<Receiver<notify::Result<Event>>>,
    log: VecDeque<String>,
}

impl FolderMonitor {
    fn log(&mut self, message: String) {
        self.log.push_back(message);
        while self.log.len() > 1_000 {
            self.log.pop_front();
        }
    }

    fn start(&mut self) {
        if self.watcher.is_some() {
            return;
        }

        let Some(input) = self.input.clone() else {
            self.log("Select an Input folder first.".into());
            return;
        };

        let (sender, receiver) = mpsc::channel::<notify::Result<Event>>();

        let result = RecommendedWatcher::new(
            move |event: notify::Result<Event>| {
                let _ = sender.send(event);
            },
            Config::default(),
        );

        let mut watcher = match result {
            Ok(watcher) => watcher,
            Err(error) => {
                self.log(format!("Could not create watcher: {error}"));
                return;
            }
        };

        if let Err(error) = watcher.watch(&input, RecursiveMode::NonRecursive) {
            self.log(format!("Could not watch {}: {error}", input.display()));
            return;
        }

        self.receiver = Some(receiver);
        // Retain the watcher: dropping it stops monitoring.
        self.watcher = Some(watcher);
        self.log(format!("Monitoring {}", input.display()));
    }
}

fn folder_row(ui: &mut egui::Ui, label: &str, folder: &mut Option<PathBuf>) {
    ui.horizontal(|ui| {
        if ui.button(format!("Select {label} folder")).clicked() {
            if let Some(path) = rfd::FileDialog::new().pick_folder() {
                *folder = Some(path);
            }
        }

        ui.label(
            folder
                .as_ref()
                .map(|path| path.display().to_string())
                .unwrap_or_else(|| "(not selected)".into()),
        );
    });
}

impl eframe::App for FolderMonitor {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        // Drain messages without blocking the GUI.
        let pending: Vec<_> = self
            .receiver
            .as_ref()
            .map(|receiver| receiver.try_iter().collect())
            .unwrap_or_default();

        for result in pending {
            match result {
                Ok(event) => {
                    let paths = event
                        .paths
                        .iter()
                        .map(|path| path.display().to_string())
                        .collect::<Vec<_>>()
                        .join(", ");

                    self.log(format!("{:?}: {paths}", event.kind));
                }
                Err(error) => self.log(format!("Watch error: {error}")),
            }
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            // Keep the displayed input consistent with the active watch.
            ui.add_enabled_ui(self.watcher.is_none(), |ui| {
                folder_row(ui, "Input", &mut self.input);
            });
            folder_row(ui, "Output", &mut self.output);
            folder_row(ui, "Done", &mut self.done);

            ui.horizontal(|ui| {
                if ui
                    .add_enabled(self.watcher.is_none(), egui::Button::new("Start"))
                    .clicked()
                {
                    self.start();
                }

                if ui
                    .add_enabled(self.watcher.is_some(), egui::Button::new("Stop"))
                    .clicked()
                {
                    self.watcher = None;
                    self.receiver = None;
                    self.log("Monitoring stopped.".into());
                }
            });

            ui.separator();
            ui.label("Filesystem events:");

            egui::ScrollArea::vertical()
                .stick_to_bottom(true)
                .show(ui, |ui| {
                    for message in &self.log {
                        ui.label(message);
                    }
                });
        });

        // Check for events while idle without continuously redrawing.
        if self.watcher.is_some() {
            ctx.request_repaint_after(Duration::from_millis(100));
        }
    }
}

fn main() -> eframe::Result<()> {
    eframe::run_native(
        "Folder Monitor",
        eframe::NativeOptions::default(),
        Box::new(|_cc| Box::new(FolderMonitor::default())),
    )
}
```

Run it with:

```bash
cargo run
```

This watches only the selected Input folder, not its subfolders. Filesystem notifications vary by operating system and can produce multiple events for one file. A creation event does **not** necessarily mean the file has finished being written.

