            };
            layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 105));
            layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));

            for (int row = 0; row < 3; row++)
                layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 36));

            layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 44));
            layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

            layout.Controls.Add(
                new Label { Text = "Student ID:", AutoSize = true }, 0, 0);
            layout.Controls.Add(txtID, 1, 0);
            layout.Controls.Add(
                new Label { Text = "Name:", AutoSize = true }, 0, 1);
            layout.Controls.Add(txtName, 1, 1);
            layout.Controls.Add(
                new Label { Text = "GPA (0–4):", AutoSize = true }, 0, 2);
            layout.Controls.Add(txtGPA, 1, 2);

            var buttons = new FlowLayoutPanel { Dock = DockStyle.Fill };
            var btnWrite = new Button { Text = "Write Data", AutoSize = true };
            var btnRead = new Button { Text = "Read Data", AutoSize = true };

            btnWrite.Click += WriteData_Click;
            btnRead.Click += ReadData_Click;
            buttons.Controls.AddRange(new Control[] { btnWrite, btnRead });

            layout.Controls.Add(buttons, 0, 3);
            layout.SetColumnSpan(buttons, 2);
            layout.Controls.Add(lstStudents, 0, 4);
            layout.SetColumnSpan(lstStudents, 2);
            Controls.Add(layout);
        }

        private void WriteData_Click(object? sender, EventArgs e)
        {
            string id = txtID.Text.Trim();
            string name = txtName.Text.Trim();
            string gpa = txtGPA.Text.Trim();

            string errors =
                Validator.IsPresent(id, "Student ID") +
                Validator.IsPresent(name, "Name") +
                Validator.IsPresent(gpa, "GPA");

            // Avoid reporting format errors for missing fields.
            if (id.Length > 0)
            {
                errors += Validator.IsInt32(id, "Student ID");
                errors += Validator.IsWithinRange(
                    id, "Student ID", 1, int.MaxValue);
            }

            if (gpa.Length > 0)
            {
                errors += Validator.IsDecimal(gpa, "GPA");
                errors += Validator.IsWithinRange(gpa, "GPA", 0, 4);
            }

            if (errors != "")
            {
                MessageBox.Show(this, errors, "Invalid input",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                // Preserve existing records by reading before rewriting.
                // If reading fails, do not attempt to overwrite the file.
                List<Student> students = StudentDB.GetStudents();
                students.Add(new Student
                {
                    StudentID = int.Parse(id),
                    Name = name,
                    GPA = decimal.Parse(gpa)
                });

                StudentDB.SaveStudents(students);

                // Clear input only after saving succeeds.
                txtID.Clear();
                txtName.Clear();
                txtGPA.Clear();
                txtID.Focus();

                MessageBox.Show(this, "Student data saved.", "Success");
            }
            catch (Exception ex)
            {
                MessageBox.Show(this, $"Could not save data:\n{ex.Message}",
                    "File error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void ReadData_Click(object? sender, EventArgs e)
        {
            try
            {
                List<Student> students = StudentDB.GetStudents();
                lstStudents.Items.Clear();

                foreach (Student student in students)
                    lstStudents.Items.Add(student);

                if (students.Count == 0)
                    MessageBox.Show(this, "No student records found.");
            }
            catch (Exception ex)
            {
                MessageBox.Show(this, $"Could not read data:\n{ex.Message}",
                    "File error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }

    internal static class Program
    {
        [STAThread]
        private static void Main()
        {
            ApplicationConfiguration.Initialize();
            Application.Run(new StudentForm());
        }
    }
}
```

**Behavior:** “Write Data” validates and adds one student while preserving existing records; “Read Data” displays all saved students. Numeric parsing follows the computer’s current culture.

