### 3. GameMode implementation

```cpp
// MyGameMode.cpp
#include "MyGameMode.h"
#include "AudioCapture.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    // Dedicated servers should not attempt local microphone capture.
    if (GetNetMode() == NM_DedicatedServer)
    {
        return;
    }

    AudioCapture = NewObject<UAudioCapture>(this);

    if (!AudioCapture ||
        !AudioCapture->OpenDefaultAudioStream())
    {
        UE_LOG(LogTemp, Warning,
            TEXT("Could not open the default microphone."));
        AudioCapture = nullptr;
        return;
    }

    AudioCapture->StartCapturingAudio();

    UE_LOG(LogTemp, Log, TEXT("Microphone capture active: %s"),
        AudioCapture->IsCapturingAudio() ? TEXT("yes") : TEXT("no"));
}

void AMyGameMode::EndPlay(
    const EEndPlayReason::Type EndPlayReason)
{
    if (AudioCapture)
    {
        AudioCapture->StopCapturingAudio();
        AudioCapture = nullptr;
    }

    Super::EndPlay(EndPlayReason);
}
```

