```python
from textual import on
from textual.app import App, ComposeResult
from textual.containers import Horizontal, VerticalScroll
from textual.widgets import Button, Footer, Header


class FileRow(Horizontal):
    def __init__(self, file_name: str) -> None:
        super().__init__()
        self.file_name = file_name

    def compose(self) -> ComposeResult:
        yield Button(self.file_name, classes="select-file")
        yield Button("Delete", variant="error", classes="delete-file")

    @on(Button.Pressed, ".select-file")
    def select_file(self, event: Button.Pressed) -> None:
        event.stop()
        self.app.notify(f"Selected: {self.file_name}")

    @on(Button.Pressed, ".delete-file")
    async def delete_file(self, event: Button.Pressed) -> None:
        # Keep this action from bubbling to ancestor message handlers.
        event.stop()
        await self.remove()


class FileApp(App):
    CSS = """
    #files {
        height: 1fr;
    }

    FileRow {
        height: 5;
        margin: 0 1 1 1;
        border: solid $primary;
    }

    .select-file {
        width: 1fr;
        min-width: 1;
    }

    .delete-file {
        width: 12;
        min-width: 12;
    }
    """

    BINDINGS = [("q", "quit", "Quit")]

    def compose(self) -> ComposeResult:
        yield Header()
        with VerticalScroll(id="files"):
            for name in ["document.txt", "photo.png", "notes.md"]:
                yield FileRow(name)
        yield Footer()


if __name__ == "__main__":
    FileApp().run()
```

The two buttons are siblings inside one row, not literally nested buttons. For actual disk deletion, the Delete handler should work with a real file path, request confirmation, handle filesystem errors, and remove the row only after deletion succeeds.

