```

That stores a reference to the moving Transform—not a snapshot. Consequently, both `startMarker.position` and `startMarker.rotation` change during the animation.

There are also a few other issues:

- `journeyAmount` uses the previous frame’s `distance`, which also isn’t reset between moves.
- `StopCoroutine(move())` creates a new enumerator; it does not stop the running one.
- Repeated calls to `moveToCenter()` start overlapping coroutines and overwrite their shared movement fields.
- The animation should explicitly set its final position and rotation.

Here is a replacement that snapshots the endpoints and cancels any previous movement:

```csharp
using System.Collections;
using UnityEngine;

public class moveCard : MonoBehaviour
{
    public storage Storage;
    public float speed = 20f;
    public int dir = 1;

    private Vector3 endPos;
    private Coroutine movement;

    void Awake()
    {
        if (Storage != null && gameObject.name == "reference")
            Storage.movePos = transform.position;
    }

    public void moveToCenter()
    {
        if (Storage == null)
            return;

        if (movement != null)
        {
            StopCoroutine(movement);
            movement = null;
        }

        Vector3 startPos = transform.position;
        Quaternion startRot = transform.rotation;

        endPos = new Vector3(
            Storage.movePos.x * dir,
            Storage.movePos.y,
            Storage.movePos.z
        );

        Quaternion endRot = Quaternion.Euler(Storage.rot);
        float length = Vector3.Distance(startPos, endPos);

        if (length <= 0.0001f)
        {
            transform.position = endPos;
            transform.rotation = endRot;
            return;
        }

        if (speed <= 0f)
        {
            Debug.LogWarning("Movement speed must be positive.");
            return;
        }

        movement = StartCoroutine(Move(
            startPos, endPos, startRot, endRot, length / speed
        ));
    }

    private IEnumerator Move(
        Vector3 startPos, Vector3 targetPos,
        Quaternion startRot, Quaternion targetRot,
        float duration)
    {
        float startTime = Time.time;

        while (Time.time - startTime < duration)
        {
            float t = (Time.time - startTime) / duration;

            transform.position = Vector3.Lerp(startPos, targetPos, t);
            transform.rotation = Quaternion.Slerp(startRot, targetRot, t);

            yield return null;
        }

        transform.position = targetPos;
        transform.rotation = targetRot;
        movement = null;
    }
}
```

This removes the two-second `Invoke` and lets the animation finish according to distance and speed. If you intended a fixed two-second duration or a hard timeout, that needs different timing logic.

If the **logged value of `endPos` itself** changes, rather than just the movement looking wrong, is `moveToCenter()` being called repeatedly, or are several cards producing those logs?

