Do you mean automatic cleanup of a normal linked list, or a tracing garbage collector that also handles cycles and shared nodes? For a normal singly linked list, use C++ smart pointers:

```cpp
#include <memory>
#include <utility>

class LinkedList {
    struct Node {
        int value;
        std::unique_ptr<Node> next;

        explicit Node(int v) : value(v) {}
    };

    std::unique_ptr<Node> head;

public:
    void push_front(int value) {
        auto node = std::make_unique<Node>(value);
        node->next = std::move(head);
        head = std::move(node);
    }

    void pop_front() {
        if (head) {
            auto old = std::move(head);
            head = std::move(old->next);
            // old deletes the removed node automatically.
        }
    }

    ~LinkedList() {
        // Iterative cleanup avoids deeply recursive destruction
        // that could overflow the stack for very long lists.
        while (head) {
            pop_front();
        }
    }
};

int main() {
    LinkedList list;
    list.push_front(10);
    list.push_front(20);
    list.pop_front();
} // Remaining nodes are freed automatically.
```

Compile with **C++14 or later**. This uses **RAII ownership**, not tracing garbage collection: each node has one owner, and destruction releases its memory automatically. If you do not need a custom implementation, `std::forward_list<int>` already manages its nodes for you.

