Below is a self-contained SwiftUI implementation. It assumes **best of three sets**, standard advantage scoring, and a **seven-point tiebreak at 6–6 in every set**, won by two points. If you need a different deciding-set format, the scoring rules should be adjusted.

Users tap the player who **won the point**. In advanced mode, they can also select its outcome. For forced and unforced errors, the error belongs to the **opponent of the point winner**.

Create an iOS 16+ SwiftUI project and replace its generated app and content-view code with this:

```swift
import SwiftUI

enum PointOutcome: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced error"
    case forcedError = "Forced error"
    case ace = "Ace"
    case returnWinner = "Return winner"
    case serveWinner = "Serve winner"

    var id: String { rawValue }
}

struct PointRecord: Identifiable {
    let id = UUID()
    let setNumber: Int
    let gameNumber: Int
    let winner: Int
    let outcome: PointOutcome?
}

struct MatchState {
    var points = [0, 0]
    var games = [0, 0]
    var completedSets: [[Int]] = []
    var history: [PointRecord] = []

    var setsWon: [Int] {
        completedSets.reduce(into: [0, 0]) { result, score in
            result[score[0] > score[1] ? 0 : 1] += 1
        }
    }

    var matchWinner: Int? {
        setsWon.firstIndex(where: { $0 == 2 })
    }

    var isTiebreak: Bool {
        games == [6, 6]
    }

    var pointScore: String {
        if isTiebreak {
            return "\(points[0])–\(points[1])"
        }

        if points[0] >= 3 && points[1] >= 3 {
            if points[0] == points[1] { return "Deuce" }
            return points[0] > points[1]
                ? "Advantage Player 1"
                : "Advantage Player 2"
        }

        let labels = ["0", "15", "30", "40"]
        return "\(labels[points[0]])–\(labels[points[1]])"
    }
}

@MainActor
final class MatchModel: ObservableObject {
    @Published private(set) var state = MatchState()
    private var undoStates: [MatchState] = []

    var canUndo: Bool { !undoStates.isEmpty }

    func awardPoint(to player: Int, outcome: PointOutcome?) {
        guard (0...1).contains(player),
              state.matchWinner == nil else { return }

        undoStates.append(state)

        state.history.append(
            PointRecord(
                setNumber: state.completedSets.count + 1,
                gameNumber: state.games.reduce(0, +) + 1,
                winner: player,
                outcome: outcome
            )
        )

        let opponent = 1 - player
        let tiebreak = state.isTiebreak
        state.points[player] += 1

        let target = tiebreak ? 7 : 4
        guard state.points[player] >= target,
              state.points[player] - state.points[opponent] >= 2
        else { return }

        state.games[player] += 1
        state.points = [0, 0]

        let setFinished =
            tiebreak ||
            (state.games[player] >= 6 &&
             state.games[player] - state.games[opponent] >= 2)

        if setFinished {
            state.completedSets.append(state.games)
            state.games = [0, 0]
        }
    }

    func undo() {
        guard let previous = undoStates.popLast() else { return }
        state = previous
    }

    func reset() {
        state = MatchState()
        undoStates.removeAll()
    }
}

