- A point history and undo.

For error categories, select the **player who won the point**; the error is attributed to their opponent.

```swift
import SwiftUI

enum PointKind: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced error"
    case forcedError = "Forced error"
    case ace = "Ace"
    case returnWinner = "Return winner"
    case serveWinner = "Serve winner"

    var id: String { rawValue }

    var isError: Bool {
        self == .unforcedError || self == .forcedError
    }
}

struct FinishedSet {
    let games: [Int]
    let tiebreak: [Int]?
}

struct ScoreState {
    var games = [0, 0]
    var points = [0, 0]
    var setsWon = [0, 0]
    var finishedSets: [FinishedSet] = []
    var matchWinner: Int?

    var isTiebreak: Bool { games == [6, 6] }

    var pointScore: String {
        if isTiebreak {
            return "\(points[0])–\(points[1]) (tiebreak)"
        }

        if points[0] >= 3 && points[1] >= 3 {
            if points[0] == points[1] { return "Deuce" }
            return "Advantage Player \(points[0] > points[1] ? 1 : 2)"
        }

        let labels = ["0", "15", "30", "40"]
        return "\(labels[points[0]])–\(labels[points[1]])"
    }
}

struct PointEntry: Identifiable {
    let id = UUID()
    let winner: Int
    let kind: PointKind?
    let before: ScoreState

    var description: String {
        let result = "Player \(winner + 1) won"
        guard let kind else { return result }

        let actor = kind.isError ? 1 - winner : winner
        return "\(result) • \(kind.rawValue) by Player \(actor + 1)"
    }

    var context: String {
        let setNumber = before.finishedSets.count + 1
        return """
        Set \(setNumber), games \(before.games[0])–\(before.games[1]), \
        \(before.pointScore)
        """
    }
}

final class MatchStore: ObservableObject {
    @Published private(set) var score = ScoreState()
    @Published private(set) var history: [PointEntry] = []

    func awardPoint(to player: Int, kind: PointKind?) {
        guard (0...1).contains(player),
              score.matchWinner == nil else { return }

        let before = score
        let opponent = 1 - player
        var next = score

        next.points[player] += 1

        let target = next.isTiebreak ? 7 : 4
        let wonGame = next.points[player] >= target
            && next.points[player] - next.points[opponent] >= 2

        if wonGame {
            // Preserve the final tiebreak points before resetting.
            let tiebreakResult = next.isTiebreak ? next.points : nil
            next.games[player] += 1
            next.points = [0, 0]

            let wonSet = tiebreakResult != nil
                || (next.games[player] >= 6
                    && next.games[player] - next.games[opponent] >= 2)

            if wonSet {
                next.finishedSets.append(
                    FinishedSet(
                        games: next.games,
                        tiebreak: tiebreakResult
                    )
                )
                next.setsWon[player] += 1

                if next.setsWon[player] == 2 {
                    next.matchWinner = player
                } else {
                    next.games = [0, 0]
                }
            }
        }

        history.append(
            PointEntry(winner: player, kind: kind, before: before)
        )
        score = next
    }

    func undo() {
        guard let entry = history.popLast() else { return }
        score = entry.before
    }

    func reset() {
        score = ScoreState()
        history = []
    }
}

struct ContentView: View {
    @StateObject private var match = MatchStore()
    @State private var advanced = false
    @State private var kind: PointKind = .winner
    @State private var confirmReset = false

    var body: some View {
        NavigationStack {
            List {
                Section("Match score") {
                    Text(
                        "Sets: \(match.score.setsWon[0])–"
                        + "\(match.score.setsWon[1])"
                    )
                    .font(.headline)

                    ForEach(
                        match.score.finishedSets.indices,
                        id: \.self
                    ) { index in
                        let set = match.score.finishedSets[index]
                        VStack(alignment: .leading) {
                            Text(
                                "Set \(index + 1): "
                                + "\(set.games[0])–\(set.games[1])"
                            )
                            if let points = set.tiebreak {
                                Text("Tiebreak: \(points[0])–\(points[1])")
                                    .font(.caption)
                            }
                        }
                    }

                    if let winner = match.score.matchWinner {
                        Text("Player \(winner + 1) wins the match")
                            .font(.headline)
                    } else {
                        Text("Set \(match.score.finishedSets.count + 1)")
                        Text(
                            "Games: \(match.score.games[0])–"
                            + "\(match.score.games[1])"
                        )
                        Text(match.score.pointScore)
                            .font(.title2.monospacedDigit())
                    }
                }

                Section("Enter a point") {
                    Toggle("Advanced point tracking", isOn: $advanced)

                    if advanced {
                        Picker("Point outcome", selection: $kind) {
                            ForEach(PointKind.allCases) { outcome in
                                Text(outcome.rawValue).tag(outcome)
                            }
                        }

                        Text(
