```cpp
#include <array>
#include <string>
#include <vector>

using namespace std;

class Solution {
    struct Node {
        array<int, 26> next{}; // 0 means no child; root is index 0
        int cnt = 0;
    };

public:
    vector<int> sumPrefixScores(vector<string>& words) {
        vector<Node> nodes(1);

        for (const string& word : words) {
            int current = 0;

            for (char c : word) {
                int letter = c - 'a';
                int child = nodes[current].next[letter];

                if (child == 0) {
                    child = static_cast<int>(nodes.size());
                    nodes.emplace_back();

                    // Access by index after emplace_back: reallocation
                    // could invalidate references or pointers to nodes.
                    nodes[current].next[letter] = child;
                }

                current = child;
                ++nodes[current].cnt;
            }
        }

        vector<int> answer;
        answer.reserve(words.size());

        for (const string& word : words) {
            int current = 0;
            int score = 0;

            // Every queried word was inserted, so its path exists.
            for (char c : word) {
                current = nodes[current].next[c - 'a'];
                score += nodes[current].cnt;
            }

            answer.push_back(score);
        }

        return answer;
    }
};
```

Assuming 4-byte `int`, each node typically occupies **108 bytes**, versus roughly **240 bytes plus allocator overhead** in the original implementation on a typical 64-bit platform. The vector also handles cleanup automatically.

