```zig
const EVENT_COUNT = @intFromEnum(ControllerEvents.START) + 1;
const PACKET_SIZE = EVENT_COUNT * 4;

fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    controllerState: []const i16,
) !void {
    if (controllerState.len != EVENT_COUNT) {
        return error.InvalidControllerStateLength;
    }

    var packet: [PACKET_SIZE]u8 = undefined;

    for (controllerState, 0..) |value, index| {
        const offset = index * 4;

        std.mem.writeInt(
            i16,
            packet[offset..][0..2],
            @intCast(index),
            .little,
        );
        std.mem.writeInt(
            i16,
            packet[offset + 2 ..][0..2],
            value,
            .little,
        );
    }

    const sent = try posix.sendto(
        sock,
        &packet,
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len) {
        return error.ShortDatagramWrite;
    }
}
```

