static void udp_server(void)
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr = {0};
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr,
             sizeof(serv_addr)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* One extra byte ensures oversized datagrams are rejected even
       when recvfrom truncates them to the receive buffer size. */
    uint8_t buffer[PACKET_SIZE + 1];

    for (;;) {
        ssize_t n = recvfrom(
            sockfd, buffer, sizeof(buffer), 0, NULL, NULL
        );

        if (n < 0) {
            perror("recvfrom");
            continue;
        }

        if ((size_t)n != PACKET_SIZE) {
            fprintf(stderr, "Invalid packet length: %zd\n", n);
            continue;
        }

        int indices[EVENT_COUNT];
        int values[EVENT_COUNT];
        unsigned char seen[EVENT_COUNT] = {0};
        int valid = 1;

        /* Validate the whole frame before applying any events. */
        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            indices[i] = read_i16_le(buffer + i * 4);
            values[i] = read_i16_le(buffer + i * 4 + 2);

            int idx = indices[i];

            if (idx < 0 || (size_t)idx >= EVENT_COUNT || seen[idx]) {
                valid = 0;
