            continue;
        }

        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            int idx = indices[i];

            int rc = libevdev_uinput_write_event(
                controller,
                REGISTERED_EVENTS[idx].type,
                REGISTERED_EVENTS[idx].code,
                values[i]
            );

            if (rc < 0) {
                fprintf(stderr, "Event write failed: %s\n",
                        strerror(-rc));
            }
        }

        int rc = libevdev_uinput_write_event(
            controller, EV_SYN, SYN_REPORT, 0
        );

        if (rc < 0) {
            fprintf(stderr, "SYN_REPORT failed: %s\n", strerror(-rc));
        }
    }
}
```

