import React, { useState } from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  View,
  useWindowDimensions,
} from 'react-native';
import type {
  StyleProp,
  TextStyle,
  ViewStyle,
} from 'react-native';

export interface ExpandableTextProps {
  text: string;
  seeMoreLabel?: string;
  containerStyle?: StyleProp<ViewStyle>;
  // Use typography styles here; put spacing/layout on containerStyle.
  textStyle?: StyleProp<TextStyle>;
  onExpand?: () => void;
}

interface ContentProps extends ExpandableTextProps {
  seeMoreLabel: string;
}

function Content({
  text,
  seeMoreLabel,
  textStyle,
  onExpand,
}: ContentProps) {
  const [overflows, setOverflows] = useState(false);
  const [expanded, setExpanded] = useState(false);

  const typography = [styles.text, textStyle];

  const expand = () => {
    setExpanded(true);
    onExpand?.();
  };

  return (
    <View>
      {/* Measure the original text at the full available width.
          Do not apply numberOfLines to this copy. */}
      <Text
        style={[typography, styles.measurement]}
        pointerEvents="none"
        accessible={false}
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        onTextLayout={({ nativeEvent }) => {
          setOverflows(nativeEvent.lines.length > 1);
        }}
      >
        {text}
      </Text>

      {expanded ? (
        <Text style={typography}>{text}</Text>
      ) : (
        <View style={styles.row}>
          <Text
            style={[typography, styles.preview]}
            numberOfLines={1}
            ellipsizeMode="tail"
          >
            {text}
          </Text>

          {overflows && (
            <Pressable
              onPress={expand}
              accessibilityRole="button"
              accessibilityLabel={seeMoreLabel}
              accessibilityHint="Shows the full text"
              accessibilityState={{ expanded: false }}
              hitSlop={8}
              style={({ pressed }) => [
                styles.button,
                pressed && styles.pressed,
              ]}
            >
              <Text
                numberOfLines={1}
                style={[typography, styles.link]}
              >
                {seeMoreLabel}
              </Text>
            </Pressable>
          )}
        </View>
      )}
    </View>
  );
}

export default function ExpandableText({
  text,
  seeMoreLabel = 'See more',
  containerStyle,
  textStyle,
  onExpand,
}: ExpandableTextProps) {
  const [width, setWidth] = useState(0);
  const { fontScale } = useWindowDimensions();

  // Remount the measurement/content when layout inputs change.
  // This deliberately resets expansion on text, width, or typography changes.
  const contentKey = JSON.stringify([
    text,
    width,
    fontScale,
    StyleSheet.flatten(textStyle),
    seeMoreLabel,
  ]);

  return (
    <View style={containerStyle}>
      <View
        style={styles.host}
        onLayout={({ nativeEvent }) => {
          setWidth(nativeEvent.layout.width);
        }}
      >
        {width > 0 && (
          <Content
            key={contentKey}
            text={text}
            seeMoreLabel={seeMoreLabel}
            textStyle={textStyle}
            onExpand={onExpand}
          />
        )}
      </View>
    </View>
  );
}

