```js
function highlightQuotedText(root) {
	const walker = document.createTreeWalker(
		root,
		NodeFilter.SHOW_TEXT,
		{
			acceptNode(node) {
				return node.parentElement.closest(
					"pre, code, script, style, textarea, .md-quote"
				)
					? NodeFilter.FILTER_REJECT
					: NodeFilter.FILTER_ACCEPT;
			}
		}
	);

	// Collect nodes first so replacing them cannot interrupt traversal.
	const nodes = [];
	while (walker.nextNode()) {
		nodes.push(walker.currentNode);
	}

	for (const node of nodes) {
		const text = node.nodeValue;
		const matches = [...text.matchAll(/"[^"]+"|“[^”]+”/g)];

		if (!matches.length) {
			continue;
		}

		const fragment = document.createDocumentFragment();
		let position = 0;

		for (const match of matches) {
			fragment.append(
				document.createTextNode(text.slice(position, match.index))
			);

			const span = document.createElement("span");
			span.className = "md-quote";
			span.style.color = "red";
			span.textContent = match[0];
			fragment.append(span);

			position = match.index + match[0].length;
		}

		fragment.append(document.createTextNode(text.slice(position)));
		node.replaceWith(fragment);
	}
}
```

