### Generate the input point mesh

Use this helper in a Unity C# script and assign the returned mesh to a `MeshFilter`. Assign a material using the shader to its `MeshRenderer`.

```csharp
using UnityEngine;
using UnityEngine.Rendering;

public static class TexelPointMesh
{
    public static Mesh Create(
        Texture texture, Vector2 size, float maxExtrusion)
    {
        int width = texture.width;
        int height = texture.height;
        int count = checked(width * height);

        var positions = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < height; y++)
        for (int x = 0; x < width; x++)
        {
            int i = y * width + x;
            Vector2 uv = new Vector2(
                (x + 0.5f) / width,
                (y + 0.5f) / height);

            uvs[i] = uv;
            positions[i] = new Vector3(
                (uv.x - 0.5f) * size.x,
                (uv.y - 0.5f) * size.y,
                0);

            indices[i] = i;
        }

        var mesh = new Mesh
        {
            name = "Texel points",
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        mesh.vertices = positions;
        mesh.uv = uvs;
        mesh.SetIndices(indices, MeshTopology.Points, 0);

        // Unity does not automatically account for shader-generated geometry.
        float depth = Mathf.Max(0, maxExtrusion);
        mesh.bounds = new Bounds(
            new Vector3(0, 0, depth * 0.5f),
            new Vector3(
                Mathf.Abs(size.x),
                Mathf.Abs(size.y),
                Mathf.Max(depth, 0.01f)));

        return mesh;
    }
}
```

Set `_Size` to the same size used for the mesh, and keep `_Extrude` within the mesh’s configured maximum extrusion. Use a positive size, and optionally preserve the image aspect ratio with `size.x / size.y = texture.width / texture.height`.

**Limitations:**
- This is unlit, with binary alpha rejection; semitransparent texels become opaque blocks.
- Use Point filtering for a crisp texel interpretation.
- Geometry shaders require a supported graphics API/device; Metal and WebGL do not support them.
- Every accepted texel emits 12 triangles, including internal faces between adjacent blocks. Start with a small texture; large images are better served by a generated mesh or compute-based approach.

