            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 positionCS : SV_POSITION;
                float4 color : COLOR0;
            };

            v2g vert(appdata v)
