                v2g o;
                o.positionOS = v.vertex;
                o.uv = v.uv;
                return o;
            }

            // Four vertices form two triangles in a triangle strip.
            void EmitFace(
                float3 a, float3 b, float3 c, float3 d,
                float4 color,
                inout TriangleStream<g2f> stream)
            {
                g2f o;
                o.color = color;

                o.positionCS = UnityObjectToClipPos(float4(a, 1));
                stream.Append(o);
                o.positionCS = UnityObjectToClipPos(float4(b, 1));
                stream.Append(o);
                o.positionCS = UnityObjectToClipPos(float4(c, 1));
                stream.Append(o);
                o.positionCS = UnityObjectToClipPos(float4(d, 1));
                stream.Append(o);

                stream.RestartStrip();
            }

            [maxvertexcount(24)]
            void geom(
                point v2g input[1],
                inout TriangleStream<g2f> stream)
            {
                // GS sampling requires an explicit mip level.
                float4 color =
                    tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));

                if (color.a <= _AlphaCutoff)
                    return;

                // Accepted texels are rendered as opaque solid columns.
                color.a = 1;

                float2 center = input[0].positionOS.xy * _Size.xy;
                float2 halfSize =
                    0.5 * _MainTex_TexelSize.xy * _Size.xy;

                float3 a = float3(center + float2(-halfSize.x, -halfSize.y), 0);
                float3 b = float3(center + float2( halfSize.x, -halfSize.y), 0);
                float3 c = float3(center + float2(-halfSize.x,  halfSize.y), 0);
                float3 d = float3(center + float2( halfSize.x,  halfSize.y), 0);

                float3 offset = float3(0, 0, _Extrude);
                float3 A = a + offset;
                float3 B = b + offset;
                float3 C = c + offset;
                float3 D = d + offset;

                EmitFace(a, b, c, d, color, stream); // Base
                EmitFace(A, B, C, D, color, stream); // Cap
                EmitFace(a, b, A, B, color, stream); // Bottom edge
                EmitFace(c, d, C, D, color, stream); // Top edge
                EmitFace(a, c, A, C, color, stream); // Left edge
                EmitFace(b, d, B, D, color, stream); // Right edge
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return i.color;
            }
            ENDCG
        }
