### Create the point mesh

Use this utility from a C# script:

```csharp
using UnityEngine;
using UnityEngine.Rendering;

public static class TexelPointMesh
{
    public static Mesh Create(
        Texture texture, Vector2 planeSize, float extrusion)
    {
        int width = texture.width;
        int height = texture.height;
        int count = checked(width * height);

        var vertices = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < height; y++)
        for (int x = 0; x < width; x++)
        {
            int i = y * width + x;

            // Sample exactly at the texel center.
            Vector2 uv = new Vector2(
                (x + 0.5f) / width,
                (y + 0.5f) / height);

            uvs[i] = uv;
            vertices[i] = new Vector3(uv.x - 0.5f, uv.y - 0.5f, 0);
            indices[i] = i;
        }

        var mesh = new Mesh
        {
            name = "Texel Points",
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        mesh.vertices = vertices;
        mesh.uv = uvs;
        mesh.SetIndices(indices, MeshTopology.Points, 0);

        // Unity's CPU culling cannot see shader-generated geometry.
        mesh.bounds = new Bounds(
            new Vector3(0, 0, extrusion * 0.5f),
            new Vector3(
                Mathf.Abs(planeSize.x) + 0.01f,
                Mathf.Abs(planeSize.y) + 0.01f,
                Mathf.Abs(extrusion) + 0.01f));

        return mesh;
    }
}
```

Assign the returned mesh to a `MeshFilter`, and assign a material using the shader to its `MeshRenderer`. Set `_MainTex`, `_Size`, and `_Extrude` to the same values used when creating the mesh. Update its bounds if those dimensions change.

**Notes:**
- Use Point filtering and disable mipmaps for predictable pixel-art sampling. The texture does not need CPU Read/Write enabled.
- This is unlit, alpha-tested geometry, not blended transparency. With cutoff zero, every texel with alpha greater than zero generates a column.
- Geometry shaders require a supported graphics API, such as desktop Direct3D 11; they are not supported on Metal.
- This emits all six faces, including hidden faces between neighboring columns. Large textures are expensive; compute-generated or prebuilt meshes are often preferable.
- Dispose of the generated mesh when no longer needed.

