Use **MVVM with an injectable recording service**. For an equalizer-*like* recording indicator, `AVAudioRecorder` metering is sufficient: you do not need a second audio engine. The bars below show recent microphone levels, not a frequency spectrum.

This example targets **iOS 17+**, saves AAC recordings in Documents, provides separate Start and Stop buttons, and handles permission denial and startup errors.

### 1. Add microphone permission

Add this entry to your target’s Info settings:

```xml
<key>NSMicrophoneUsageDescription</key>
<string>Record your voice and save audio recordings.</string>
```

Without this description, attempting microphone access can terminate the app.

### 2. Recording service

```swift
// RecordingService.swift
import AVFoundation
import Foundation

enum RecordingError: LocalizedError {
    case permissionDenied
    case couldNotStart

    var errorDescription: String? {
        switch self {
        case .permissionDenied:
            return "Microphone access is disabled. Enable it in Settings."
        case .couldNotStart:
            return "The audio recording could not be started."
        }
    }
}

@MainActor
protocol RecordingService: AnyObject {
    func start() throws
    func sampleLevel() -> Float
    func stop() -> URL?
}

@MainActor
final class AudioRecordingService: RecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func start() throws {
        guard recorder == nil else { return }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        let url = directory.appendingPathComponent(
            "\(UUID().uuidString).m4a"
        )

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(
                url: url,
                settings: settings
            )
            newRecorder.isMeteringEnabled = true

            guard newRecorder.prepareToRecord(),
                  newRecorder.record() else {
                throw RecordingError.couldNotStart
            }

            recorder = newRecorder
        } catch {
            try? FileManager.default.removeItem(at: url)
            deactivateSession()
            throw error
        }
    }

    func sampleLevel() -> Float {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let decibels = recorder.averagePower(forChannel: 0)

        // A display mapping, not a measurement of frequency content.
        return min(max((decibels + 60) / 60, 0), 1)
    }

    func stop() -> URL? {
        guard let recorder else { return nil }

        recorder.stop() // Finishes the current recording file.
        let url = recorder.url
        self.recorder = nil
        deactivateSession()
        return url
    }

    private func deactivateSession() {
        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }
}
```

### 3. View model

All UI state is main-actor isolated. A cancellable task requests permission and samples microphone levels at approximately 20 Hz.

```swift
// RecorderViewModel.swift
import AVFoundation
import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var isStarting = false
    @Published private(set) var levels =
        Array(repeating: Float.zero, count: 24)
    @Published private(set) var savedURL: URL?
    @Published var errorMessage: String?

    private let service: any RecordingService
    private var recordingTask: Task<Void, Never>?

    init(service: any RecordingService) {
        self.service = service
    }

    func start() {
        guard !isRecording, !isStarting else { return }

        isStarting = true
        errorMessage = nil

        recordingTask = Task { @MainActor [weak self] in
            let granted = await AVAudioApplication.requestRecordPermission()

            // Stop may have been pressed, or the view may have disappeared,
            // while the system permission prompt was visible.
            guard !Task.isCancelled, let self else { return }
            self.isStarting = false

            guard granted else {
                self.errorMessage =
                    RecordingError.permissionDenied.localizedDescription
                return
            }

            do {
                try self.service.start()
                self.isRecording = true
                self.levels = Array(repeating: 0, count: 24)
            } catch {
                self.errorMessage = error.localizedDescription
                return
            }

            // Do not retain the view model indefinitely in a polling loop.
            self.beginMetering()
        }
    }

    private func beginMetering() {
        recordingTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard let self, self.isRecording else { return }

                self.levels.removeFirst()
                self.levels.append(self.service.sampleLevel())

                do {
                    try await Task.sleep(for: .milliseconds(50))
                } catch {
                    return
                }
            }
        }
    }

    func stop() {
        recordingTask?.cancel()
        recordingTask = nil
        isStarting = false

        if let url = service.stop() {
            savedURL = url
        }

        isRecording = false
        levels = Array(repeating: 0, count: 24)
    }
}
```

### 4. Visualizer and recording screen

The visualizer uses stable bar identities and actual microphone samples; it does not generate random values inside `body`.

