            let spacing: CGFloat = 3
            let width = max(
                1,
                (geometry.size.width
                    - spacing * CGFloat(levels.count - 1))
                    / CGFloat(levels.count)
            )

            HStack(alignment: .center, spacing: spacing) {
                ForEach(levels.indices, id: \.self) { index in
                    Capsule()
                        .fill(isRecording ? Color.red : Color.gray)
                        .frame(
                            width: width,
                            height: max(
                                4,
                                CGFloat(levels[index])
                                    * geometry.size.height
                            )
                        )
                }
            }
            .frame(height: geometry.size.height)
        }
        .animation(.linear(duration: 0.05), value: levels)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(
            isRecording ? "Recording audio" : "Not recording"
        )
    }
}

@MainActor
struct VoiceRecorderView: View {
    @Environment(\.scenePhase) private var scenePhase

    @StateObject private var model = RecorderViewModel(
        service: AudioRecordingService()
    )

    var body: some View {
        VStack(spacing: 24) {
            Text("Voice Recorder")
                .font(.largeTitle.bold())

            Spacer()

            RecordingVisualizer(
                levels: model.levels,
                isRecording: model.isRecording
            )
            .frame(height: 150)

            Text(model.isRecording ? "Recording…" : "Ready")
                .foregroundStyle(.secondary)

            Spacer()

            if let url = model.savedURL {
                ShareLink(item: url) {
                    Label("Share saved recording", systemImage: "square.and.arrow.up")
                }
            }

            HStack {
                Button("Start", systemImage: "mic.fill") {
                    model.start()
                }
                .disabled(model.isRecording || model.isStarting)

                Button("Stop & Save", systemImage: "stop.fill") {
                    model.stop()
                }
                .disabled(!model.isRecording && !model.isStarting)
            }
            .buttonStyle(.borderedProminent)
        }
        .padding(24)
        .alert(
            "Recording error",
            isPresented: Binding(
                get: { model.errorMessage != nil },
                set: { if !$0 { model.errorMessage = nil } }
            )
        ) {
            Button("OK") { model.errorMessage = nil }
        } message: {
            Text(model.errorMessage ?? "")
        }
        .onDisappear {
            model.stop()
        }
        .onChange(of: scenePhase) { _, phase in
            // This example intentionally does not record in the background.
            if phase == .background {
                model.stop()
            }
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: AVAudioSession.interruptionNotification
            )
        ) { notification in
            if let raw = notification.userInfo?[
                AVAudioSessionInterruptionTypeKey
            ] as? UInt,
               raw == AVAudioSession.InterruptionType.began.rawValue {
                model.stop()
            }
        }
    }
}
