        guard !isRecording, !isStarting else { return }

        let request = UUID()
        startRequest = request
        isStarting = true
        errorMessage = nil

        let granted = await service.requestPermission()

        // Ignore a permission response if the view has already closed.
        guard startRequest == request else { return }

        defer {
            isStarting = false
            startRequest = nil
        }

        guard granted else {
            errorMessage = RecordingError.permissionDenied.localizedDescription
            return
        }

        do {
            try service.start()
            savedURL = nil
            levels = Array(repeating: 0, count: levels.count)
            isRecording = true
            startMetering()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    func finish() {
        startRequest = nil
        isStarting = false

        meterTimer?.invalidate()
        meterTimer = nil

        if let url = service.stop() {
            savedURL = url
        }

        isRecording = false
        levels = Array(repeating: 0, count: levels.count)
    }

    private func startMetering() {
        meterTimer?.invalidate()

        let timer = Timer(timeInterval: 0.08, repeats: true) {
            [weak self] _ in
            Task { @MainActor [weak self] in
                guard let self, self.isRecording else { return }

                self.levels.removeFirst()
                self.levels.append(self.service.level())
            }
        }

        meterTimer = timer
        RunLoop.main.add(timer, forMode: .common)
    }
}
```

