Here is a replacement `fetch_svg.js`. It modifies the SVG as a DOM element rather than using a fragile text replacement, and calls `createAlarmSVGLinks()` after insertion instead of relying on an inline SVG `onload` handler.

```javascript
// fetch_svg.js

async function insertSVG() {
    const container = document.getElementById("svgContainer");

    if (!container) {
        console.error("Element #svgContainer was not found.");
        return;
    }

    try {
        const response = await fetch("../images/wtrtrmt42_01_esmx.svg");

        if (!response.ok) {
            throw new Error(`SVG request failed: HTTP ${response.status}`);
        }

        const svgText = await response.text();
        const svgDocument = new DOMParser().parseFromString(
            svgText,
            "image/svg+xml"
        );

        if (
            svgDocument.querySelector("parsererror") ||
            svgDocument.documentElement.localName !== "svg"
        ) {
            throw new Error("The response is not a valid SVG document.");
        }

        const svg = document.importNode(svgDocument.documentElement, true);

        svg.setAttribute("version", "1.1");
        svg.removeAttribute("width");
        svg.removeAttribute("height");
        svg.removeAttribute("onload");

        // Preserve the existing viewBox and scale to the container width.
        svg.style.display = "block";
        svg.style.width = "100%";
        svg.style.height = "auto";

        container.replaceChildren(svg);

        // Initialize links after the SVG elements are in the page.
        if (typeof createAlarmSVGLinks === "function") {
            createAlarmSVGLinks("../wtrtrmt_alarms.htm");
        } else {
            console.warn(
                "SVG inserted, but createAlarmSVGLinks is not defined."
            );
        }
    } catch (error) {
        console.error("Error loading SVG:", error);
    }
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", insertSVG);
} else {
    insertSVG();
}
```

