Yes. A custom FLTK widget is a good fit: it can draw inside an `Fl_Window` or another container. Here is a possible **header-only interface declaration**; the method implementations would go in a `.cpp` file.

This design supports multiple line graphs, named axes with configurable ranges, adjustable gridlines, and insertion/removal of individual points.

```cpp
#ifndef CHART_WIDGET_H
#define CHART_WIDGET_H

#include <FL/Fl_Widget.H>
#include <FL/fl_draw.H>

#include <cstddef>
#include <iosfwd>
#include <list>
#include <string>

namespace plotting {

struct Point {
    float x;
    float y;
};

using GraphId = unsigned long long;

struct AxisSettings {
    std::string name;
    float minimum = 0.0f;
    float maximum = 1.0f;
};

struct GridSettings {
    bool visible = true;
    unsigned xDivisions = 10;  // Equal intervals along X
    unsigned yDivisions = 10;  // Equal intervals along Y
    Fl_Color color = FL_LIGHT2;
    int lineStyle = FL_DOT;
    int lineWidth = 1;
};

struct Graph {
    GraphId id;
    std::string name;
    std::list<Point> points;   // Connected in insertion order
    Fl_Color color = FL_BLUE;
    int lineWidth = 1;
};

class ChartWidget : public Fl_Widget {
public:
    ChartWidget(int x, int y, int width, int height,
                const char* label = nullptr);
    ~ChartWidget() override = default;

    // Returns a stable, unique ID; graph names need not be unique.
    GraphId addGraph(const std::string& name,
                     Fl_Color color = FL_BLUE);
    bool removeGraph(GraphId id);
    bool renameGraph(GraphId id, const std::string& name);

    // Return false if the graph or point index does not exist.
    bool addPoint(GraphId id, Point point);
    bool removePoint(GraphId id, std::size_t index);
    bool clearPoints(GraphId id);

    // Return false for invalid settings, leaving state unchanged.
    // Axis limits must be finite and minimum < maximum.
    bool setXAxis(const AxisSettings& axis);
    bool setYAxis(const AxisSettings& axis);

    // Division counts and line width must be positive.
    bool setGrid(const GridSettings& grid);

    std::size_t graphCount() const noexcept;
    void showInfo(std::ostream& output) const;

protected:
    void draw() override;

private:
    Graph* findGraph(GraphId id);

    void drawGrid(int left, int top, int width, int height);
    void drawAxes(int left, int top, int width, int height);
    void drawGraphs(int left, int top, int width, int height);

    double screenX(float value, int left, int width) const;
    double screenY(float value, int top, int height) const;

    std::list<Graph> graphs_;
    GraphId nextId_ = 1;
    AxisSettings xAxis_;
    AxisSettings yAxis_;
    GridSettings grid_;
};

} // namespace plotting

#endif
```

Implementation notes:

- Call inherited `redraw()` after successful changes to data or settings.
- Reserve margins for axis names and tick labels, and clip graph drawing to the plot rectangle using `fl_push_clip()` / `fl_pop_clip()`.
- Convert data coordinates to screen coordinates using:
  ```text
  screenX = left + (x - xmin) / (xmax - xmin) * plotWidth
  screenY = top + plotHeight - (y - ymin) / (ymax - ymin) * plotHeight
  ```
- Use `fl_line()` to connect consecutive points. If the graph must represent a single-valued function, supply points in increasing X order or define a sorting policy.
- `std::list<Point>` matches the requested list structure, although `std::vector<Point>` is often faster for sequential plotting.
- The widget inherits FLTK’s geometry API, including `resize(x, y, width, height)`. Parent-window resizing behavior must be configured separately.

