<script>
"use strict";
const $ = id => document.getElementById(id);
const editor = $("editor"), paint = $("paint"), gutter = $("gutter");
const key = "pocket-codepad-v1";
let timer;

const escapeHTML = text => text.replace(/[&<>"]/g, ch =>
  ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[ch]));

function highlight(text) {
  if ($("language").value === "text") return escapeHTML(text);

  // Tokenize raw text once; never run replacements over generated spans.
  const pattern = $("language").value === "markup"
    ? /<!--[\s\S]*?(?:-->|$)|<\/?[\w:-]+(?:[^>"']|"[^"]*"|'[^']*')*>/g
    : /\/\*[\s\S]*?(?:\*\/|$)|\/\/[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:const|let|var|function|return|if|else|for|while|class|new|import|export|from|async|await|throw|try|catch|true|false|null|undefined)\b|\b\d+(?:\.\d+)?\b/g;
  let output = "", previous = 0;
  for (const match of text.matchAll(pattern)) {
    const token = match[0];
    const type = /^(\/\/|\/\*|<!--)/.test(token) ? "comment"
      : /^["'`]/.test(token) ? "string"
      : /^\d/.test(token) ? "number" : "keyword";
    output += escapeHTML(text.slice(previous, match.index));
    output += `<span class="${type}">${escapeHTML(token)}</span>`;
    previous = match.index + token.length;
  }
  return output + escapeHTML(text.slice(previous));
}

function syncScroll() {
  paint.scrollTop = editor.scrollTop;
  paint.scrollLeft = editor.scrollLeft;
  gutter.scrollTop = editor.scrollTop;
}
function stats() {
  const before = editor.value.slice(0, editor.selectionStart);
  const line = before.split("\n").length;
  const column = before.length - before.lastIndexOf("\n");
  $("stats").textContent =
    `Ln ${line}, Col ${column} · ${editor.value.length} characters · ` +
    `${editor.value.trim().match(/\S+/g)?.length || 0} words · ` +
    `${editor.selectionEnd-editor.selectionStart} selected`;
}
function persist() {
  try {
    localStorage.setItem(key, JSON.stringify({
      text:editor.value,name:$("name").value,language:$("language").value,
      light:document.body.classList.contains("light"),size:$("size").value
    }));
    $("message").textContent = "Saved locally";
  } catch {
    $("message").textContent = "Local storage unavailable; download a backup";
  }
}
function update(save = true) {
  paint.innerHTML = highlight(editor.value) + "\n";
  gutter.textContent = Array.from(
    {length:editor.value.split("\n").length}, (_,i) => i+1
  ).join("\n") + "\n";
  stats();
  syncScroll();
  if (save) {
    clearTimeout(timer);
    timer = setTimeout(persist, 250);
  }
}
function insert(text) {
  editor.setRangeText(text, editor.selectionStart, editor.selectionEnd, "end");
  update();
  editor.focus();
}
function findNext() {
  const query = $("find").value;
  if (!query) return;
  const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(escaped, $("matchCase").checked ? "g" : "gi");
  regex.lastIndex = editor.selectionEnd;
  let match = regex.exec(editor.value);
  if (!match) {
    regex.lastIndex = 0;
    match = regex.exec(editor.value);
  }
  if (!match) {
    $("message").textContent = "No matches";
    return;
  }
  editor.focus();
  editor.setSelectionRange(match.index, match.index + match[0].length);
  editor.scrollTop =
    editor.value.slice(0, match.index).split("\n").length *
    parseFloat(getComputedStyle(editor).lineHeight) - editor.clientHeight/2;
  syncScroll();
  stats();
}
function download() {
  const url = URL.createObjectURL(new Blob([editor.value], {
    type:"text/plain;charset=utf-8"
  }));
  const link = document.createElement("a");
  link.href = url;
  link.download = $("name").value.trim() || "untitled.txt";
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  persist();
}
function inferLanguage(name) {
  $("language").value = /\.(html?|xml|svg)$/i.test(name) ? "markup"
    : /\.(js|mjs|ts|css|json)$/i.test(name) ? "code" : "text";
}
editor.addEventListener("input", () => update());
editor.addEventListener("scroll", syncScroll);
document.addEventListener("selectionchange", stats);
editor.addEventListener("keydown", event => {
  if (event.key === "Tab") {
    event.preventDefault();
    insert("  ");
  } else if (event.key === "Enter") {
    event.preventDefault();
    const preceding = editor.value.slice(0, editor.selectionStart).split("\n").pop();
    const indent = preceding.match(/^[\t ]*/)[0];
    insert("\n" + indent + (/[{[:]\s*$/.test(preceding) ? "  " : ""));
  }
});
document.addEventListener("keydown", event => {
  if (!(event.ctrlKey || event.metaKey)) return;
  const k = event.key.toLowerCase();
  if (k === "s") { event.preventDefault(); download(); }
  if (k === "f") { event.preventDefault(); $("find").focus(); }
});
$("save").onclick = download;
$("open").onclick = () => $("file").click();
$("file").onchange = async event => {
  const file = event.target.files[0];
  if (!file) return;
  if (editor.value && !confirm("Replace this buffer? Download a backup first if needed.")) {
    event.target.value = "";
    return;
  }
  try {
    editor.value = (await file.text()).replace(/\r\n?/g,"\n");
    $("name").value = file.name;
    inferLanguage(file.name);
    update();
  } catch { $("message").textContent = "Could not read file"; }
  event.target.value = "";
};
$("new").onclick = () => {
  if (editor.value && !confirm("Clear this buffer?")) return;
  editor.value = "";
  $("name").value = "untitled.txt";
  inferLanguage($("name").value);
  update();
  editor.focus();
};
$("theme").onclick = () => {
  document.body.classList.toggle("light");
  persist();
};
$("size").onchange = () => {
  const size = Math.max(10, Math.min(32, Number($("size").value) || 15));
  $("size").value = size;
  document.body.style.setProperty("--size", size+"px");
  syncScroll();
  persist();
};
$("language").onchange = () => update();
$("name").onchange = persist;
$("next").onclick = findNext;
$("find").onkeydown = event => { if (event.key === "Enter") findNext(); };
$("replace").onclick = () => {
  const selected = editor.value.slice(editor.selectionStart, editor.selectionEnd);
  const query = $("find").value;
  const normalize = s => $("matchCase").checked ? s : s.toLowerCase();
  if (query && normalize(selected) === normalize(query)) insert($("replacement").value);
  findNext();
};
$("all").onclick = () => {
  const query = $("find").value;
  if (!query) return;
  const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(escaped, $("matchCase").checked ? "g" : "gi");
  editor.value = editor.value.replace(regex, () => $("replacement").value);
  update();
};
$("goto").onclick = () => {
  const n = Number(prompt("Line number:"));
  const lines = editor.value.split("\n");
  if (!Number.isInteger(n) || n < 1 || n > lines.length) return;
  const position = lines.slice(0,n-1).reduce((sum,line) => sum+line.length+1,0);
  editor.focus();
  editor.setSelectionRange(position,position);
  editor.scrollTop = (n-1)*parseFloat(getComputedStyle(editor).lineHeight);
  syncScroll();
  stats();
};
try {
  const saved = JSON.parse(localStorage.getItem(key) || "null");
  if (saved && typeof saved.text === "string") {
    editor.value = saved.text;
    $("name").value = saved.name || "untitled.txt";
    $("language").value = saved.language || "text";
    document.body.classList.toggle("light", !!saved.light);
    $("size").value = Math.max(10,Math.min(32,Number(saved.size)||15));
    document.body.style.setProperty("--size", $("size").value+"px");
  }
} catch { $("message").textContent = "Could not restore local draft"; }
window.addEventListener("pagehide", persist);
update(false);
</script>
</body>
</html>
