Excel normally stores numeric cells as numbers, not as source-code literals. Thus a numeric cell containing `42.0` should pass regardless of its display format. Hexadecimal, octal, and binary literals generally need to be read from **text cells**.

The notation needs clarification: for example, `"10"` cannot unambiguously mean both decimal ten and binary two. The following solution uses these explicit conventions:

- Decimal: `42`, `42.0`, `4.2e1`
- Hexadecimal: `0x2A`
- Octal: `0o52`, or C-style `052`
- Binary: `0b101010`

It permits surrounding whitespace and an optional sign. Change these conventions if the input uses a different notation.

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QMetaType>
#include <QRegularExpression>
#include <QString>
#include <QVariant>
#include <cmath>

#include "xlsxdocument.h"

static bool allowed(double value)
{
    // Exact comparison: do not round or use a floating-point tolerance.
    return std::isfinite(value) &&
           (value == 0 || value == 1 || value == 2 ||
            value == 3 || value == 10 || value == 11 ||
            value == 42);
}

static bool allowedText(QString text)
{
    text = text.trimmed();
    if (text.isEmpty())
        return false;

    bool negative = false;
    if (text.startsWith(QLatin1Char('+')) ||
        text.startsWith(QLatin1Char('-'))) {
        negative = text.startsWith(QLatin1Char('-'));
        text.remove(0, 1);
    }

    if (text.isEmpty())
        return false;

    int base = 10;
    QString digits = text;

    if (text.startsWith("0x", Qt::CaseInsensitive)) {
        base = 16;
        digits.remove(0, 2);
    } else if (text.startsWith("0b", Qt::CaseInsensitive)) {
        base = 2;
        digits.remove(0, 2);
    } else if (text.startsWith("0o", Qt::CaseInsensitive)) {
        base = 8;
        digits.remove(0, 2);
    } else {
        static const QRegularExpression leadingZeroInteger(
            QStringLiteral("\\A0[0-9]+\\z"));
        if (leadingZeroInteger.match(text).hasMatch())
            base = 8;
    }

    if (base != 10) {
        const QString pattern =
            base == 16 ? QStringLiteral("\\A[0-9a-fA-F]+\\z") :
            base == 8  ? QStringLiteral("\\A[0-7]+\\z") :
                         QStringLiteral("\\A[01]+\\z");

        if (!QRegularExpression(pattern).match(digits).hasMatch())
            return false;

        bool ok = false;
        const qulonglong value = digits.toULongLong(&ok, base);
        if (!ok || (negative && value != 0))
            return false;

        // Integer comparison avoids precision loss.
        return value == 0 || value == 1 || value == 2 ||
               value == 3 || value == 10 || value == 11 ||
               value == 42;
    }

    static const QRegularExpression decimal(
        QStringLiteral(
            "\\A(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)"
            "(?:[eE][+-]?[0-9]+)?\\z"));

    if (!decimal.match(text).hasMatch())
        return false;

    bool ok = false;
    double value = text.toDouble(&ok);
    if (negative)
        value = -value;
    return ok && allowed(value);
}

static bool allowedCellValue(const QVariant &value)
{
    // canConvert<double>() is not a numeric-type test:
    // QString and bool can also be convertible to double.
    switch (value.userType()) {
    case QMetaType::QString:
        return allowedText(value.toString());

    case QMetaType::Int:
    case QMetaType::UInt:
    case QMetaType::LongLong:
    case QMetaType::ULongLong:
    case QMetaType::Float:
    case QMetaType::Double: {
        bool ok = false;
        const double number = value.toDouble(&ok);
        return ok && allowed(number);
    }

    default:
        // Reject empty values, booleans, dates, and other nonnumeric types.
        return false;
    }
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);
    const QStringList args = app.arguments();

    if (args.size() != 3) {
        qCritical() << "Usage: validator file.xlsx A1";
        return 2;
    }

    QXlsx::Document workbook(args.at(1));
    if (!workbook.load()) {
        qCritical() << "Cannot load workbook";
        return 2;
    }

    // Reads from the workbook's current worksheet.
    const bool valid = allowedCellValue(workbook.read(args.at(2)));
    qInfo() << (valid ? "Allowed" : "Not allowed");
    return valid ? 0 : 1;
}
```

This uses the workbook’s current worksheet; select a worksheet explicitly if the cell belongs elsewhere. Build it in a Qt Core project linked to QXlsx.

**Precision qualification:** Numeric Excel cells and decimal text converted with `toDouble()` are checked at their represented floating-point value. If “only those” requires exact mathematical validation of arbitrarily precise decimal **text**, use an exact decimal parser instead: text such as `3.00000000000000000001` can round to `3` when converted to `double`. Already-lost precision in a numeric Excel cell cannot be recovered.

