One detail needs clarification: **what syntax denotes octal?** For example, should `"010"` mean decimal 10 or octal 8? The implementation below explicitly uses these conventions:

- `0x` / `0X`: hexadecimal
- `0b` / `0B`: binary
- `0o` / `0O`: octal
- Otherwise: decimal, including floating-point and scientific notation
- Leading zeros alone do **not** indicate octal

It rejects booleans, empty cells, malformed text, and values outside the specified set. Comparisons are exact at the numeric precision used by Excel/`double`; no fuzzy comparison or integer truncation is used.

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QMetaType>
#include <QRegularExpression>
#include <QVariant>
#include <cmath>

#include "xlsxdocument.h"

static bool allowedNumber(double value)
{
    return std::isfinite(value) &&
           (value == 0 || value == 1 || value == 2 ||
            value == 3 || value == 10 || value == 11 ||
            value == 42);
}

static bool allowedText(QString text)
{
    text = text.trimmed();
    if (text.isEmpty())
        return false;

    // Extract an optional sign before checking base prefixes.
    bool negative = false;
    if (text.startsWith('-') || text.startsWith('+')) {
        negative = text.startsWith('-');
        text.remove(0, 1);
    }

    if (text.isEmpty())
        return false;

    int base = 10;
    if (text.startsWith("0x", Qt::CaseInsensitive))
        base = 16;
    else if (text.startsWith("0b", Qt::CaseInsensitive))
        base = 2;
    else if (text.startsWith("0o", Qt::CaseInsensitive))
        base = 8;

    if (base != 10) {
        text.remove(0, 2);
        if (text.isEmpty())
            return false;

        // Parse strictly, rejecting malformed input and avoiding overflow.
        // No magnitude greater than 42 can be an allowed value.
        unsigned value = 0;
        for (QChar ch : text) {
            const ushort c = ch.unicode();
            int digit = -1;

            if (c >= '0' && c <= '9')
                digit = c - '0';
            else if (c >= 'a' && c <= 'f')
                digit = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F')
                digit = c - 'A' + 10;

            if (digit < 0 || digit >= base)
                return false;

            value = value * unsigned(base) + unsigned(digit);
            if (value > 42)
                return false;
        }

        return allowedNumber(negative ? -double(value) : double(value));
    }

    // Locale-independent decimal syntax; require the entire text to match.
    static const QRegularExpression decimal(
        QStringLiteral(
            "\\A(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)"
            "(?:[eE][+-]?[0-9]+)?\\z"));

    if (!decimal.match(text).hasMatch())
        return false;

    bool ok = false;
    double value = text.toDouble(&ok);
    return ok && allowedNumber(negative ? -value : value);
}

