### API adapter and provisioning facade

```typescript
// user-setup.ts
import type { APIRequestContext } from '@playwright/test';

export interface CreateUserInput {
  username: string;
  email: string;
}

export interface PermissionsInput {
  role: 'admin' | 'user';
}

export interface Credentials {
  username: string;
  password: string;
}

export interface ProvisionedUser {
  id: string;
  credentials: Credentials;
}

// A narrow contract allows the workflow to be unit-tested without HTTP.
export interface UsersApi {
  create(input: CreateUserInput): Promise<{ id: string }>;
  setPermissions(
    id: string,
    input: PermissionsInput,
  ): Promise<Credentials>;
  delete(id: string): Promise<void>;
}

export class PlaywrightUsersApi implements UsersApi {
  constructor(private readonly request: APIRequestContext) {}

  async create(input: CreateUserInput): Promise<{ id: string }> {
    const response = await this.request.post('/users/v2/create', {
      data: input,
    });

    if (response.status() !== 201) {
      throw new Error(`Create user failed: HTTP ${response.status()}`);
    }

    const body = await response.json();
    if (typeof body?.id !== 'string' || !body.id) {
      throw new Error('Create user returned an invalid ID');
    }

    return { id: body.id };
  }

  async setPermissions(
    id: string,
    input: PermissionsInput,
  ): Promise<Credentials> {
    const response = await this.request.post('/users/v2/permissions', {
      data: { ...input, id },
    });

    if (response.status() !== 200) {
      throw new Error(`Set permissions failed: HTTP ${response.status()}`);
    }

    const body = await response.json();
    if (
      typeof body?.username !== 'string' ||
      !body.username ||
      typeof body?.password !== 'string' ||
      !body.password
    ) {
      throw new Error('Permissions API returned invalid credentials');
    }

    return { username: body.username, password: body.password };
  }

  async delete(id: string): Promise<void> {
    // Assumed endpoint: replace with your application's deletion contract.
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // Treat "already absent" as successful cleanup.
    if (![200, 204, 404].includes(response.status())) {
      throw new Error(`Delete user failed: HTTP ${response.status()}`);
    }
  }
}

// Facade: hides the ordered, multi-API provisioning workflow.
export class UserProvisioner {
  constructor(private readonly api: UsersApi) {}

  async createAdmin(
    input: CreateUserInput,
    registerCleanup: (id: string) => void,
  ): Promise<ProvisionedUser> {
    const { id } = await this.api.create(input);

    // Register immediately so permission-update failures also trigger cleanup.
    registerCleanup(id);

    const credentials = await this.api.setPermissions(id, {
      role: 'admin',
    });

    return { id, credentials };
  }
}
```

