## 我的解答

使用**扫描线 + 离散化 + 线段树**。

将每个矩形的左、右边界分别作为加入和删除事件，按横坐标排序。相邻事件之间的面积为：

\[
\Delta x \times \text{当前所有活动矩形在 }y\text{ 轴上的覆盖总长度}
\]

线段树维护离散化后的基本区间，节点记录覆盖次数和实际覆盖长度：

- 覆盖次数大于 0：整个节点区间均被覆盖。
- 覆盖次数为 0 且是叶子：覆盖长度为 0。
- 否则：覆盖长度等于两个子节点的覆盖长度之和。

以下按每行四个空格分隔整数读取输入；零面积矩形直接忽略。

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
constexpr ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

class SegmentTree {
    const vector<ll>& ys;
    vector<int> cover;
    vector<ll> len;
    int n;

    void pull(int p, int l, int r) {
        if (cover[p] > 0) {
            len[p] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

    void update(int p, int l, int r, int ql, int qr, int delta) {
        if (qr <= l || r <= ql) return;

        if (ql <= l && r <= qr) {
            cover[p] += delta;
        } else {
            int mid = (l + r) / 2;
            update(p * 2, l, mid, ql, qr, delta);
            update(p * 2 + 1, mid, r, ql, qr, delta);
        }
        pull(p, l, r);
    }

public:
    explicit SegmentTree(const vector<ll>& coordinates)
        : ys(coordinates),
          cover(4 * coordinates.size() + 4, 0),
          len(4 * coordinates.size() + 4, 0),
          n(static_cast<int>(coordinates.size()) - 1) {}

    void update(int l, int r, int delta) {
        if (l < r) update(1, 0, n, l, r, delta);
    }

    ll coveredLength() const {
        return len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    SegmentTree tree(ys);
    ll area = 0;
    ll previousX = events.front().x;

    for (const Event& e : events) {
        area += (e.x - previousX) * tree.coveredLength();

        int l = lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
        tree.update(l, r, e.delta);

        previousX = e.x;
    }

    cout << area % MOD << '\n';
    return 0;
}
```

题目保证总面积不超过有符号 64 位整数范围，因此可以使用 `long long` 累加，最后取模。同一横坐标的事件之间宽度为 0，逐个处理不会重复计算面积。

- 时间复杂度：\(O(n\log n)\)。
- 空间复杂度：\(O(n)\)。

