### Câu trả lời của tôi

Dưới đây là chương trình C cài đặt thuật toán Euclid mở rộng, tìm `d, x, y` sao cho:

\[
a x + b y = d = \gcd(a,b).
\]

Chương trình giả sử `a, b` không âm và không đồng thời bằng 0. Các ký hiệu bị lỗi trong đề được hiểu là phép gán, chẳng hạn `x2 ← x1`.

```c
#include <stdio.h>

long long extendedEuclid(long long a, long long b,
                         long long *x, long long *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }

    long long x2 = 1, x1 = 0;
    long long y2 = 0, y1 = 1;

    while (b > 0) {
        long long q = a / b;
        long long r = a - q * b;
        long long nx = x2 - q * x1;
        long long ny = y2 - q * y1;

        a = b;
        b = r;
        x2 = x1;
        x1 = nx;
        y2 = y1;
        y1 = ny;
    }

    *x = x2;
    *y = y2;
    return a;
}

int main(void) {
    long long a, b, d, x, y;

    printf("Nhap a, b (khong am, khong dong thoi bang 0): ");
    if (scanf("%lld %lld", &a, &b) != 2 ||
        a < 0 || b < 0 || (a == 0 && b == 0)) {
        printf("Du lieu khong hop le.\n");
        return 1;
    }

    d = extendedEuclid(a, b, &x, &y);

    printf("d = %lld, x = %lld, y = %lld\n", d, x, y);
    printf("%lld*(%lld) + %lld*(%lld) = %lld\n",
           a, x, b, y, d);

    return 0;
}
```

Ví dụ, với `a = 30`, `b = 12`, kết quả là `d = 6`, `x = 1`, `y = -2`, vì `30*1 + 12*(-2) = 6`.

Hàm trả về `d` bằng `return`; hai hệ số `x, y` được trả qua con trỏ.

